function tl_refresh_cv_slug() {
    $path = isset($_SERVER['REQUEST_URI']) ? (string) parse_url($_SERVER['REQUEST_URI'], PHP_URL_PATH) : '';
    $slug = trim($path, '/');
    $pages = tl_refresh_cv_pages();
    return isset($pages[$slug]) ? $slug : null;
}
function tl_refresh_cv_route() {
    $slug = tl_refresh_cv_slug();
    if (!$slug || !is_404()) { return; }
    $pages = tl_refresh_cv_pages();
    $page = $pages[$slug];
    global $wp_query;
    $wp_query->is_404 = false;
    status_header(200);
    add_filter('pre_get_document_title', function () use ($page) {
        return $page['title'] . ' – ' . get_bloginfo('name');
    }, 99);
    add_filter('body_class', function ($classes) use ($slug) {
        $classes = array_values(array_diff($classes, array('error404', 'ast-separate-container', 'ast-two-container')));
        $classes[] = 'page';
        $classes[] = 'ast-page-builder-template';
        $classes[] = 'tl-cv-page';
        $classes[] = 'tl-cv-' . $slug;
        return $classes;
    }, 99);
    get_header();
    echo '<div id="primary" class="content-area primary"><main id="main" class="site-main"><article class="page type-page tl-cv-article"><div class="entry-content clear">';
    echo $page['html'];
    echo '</div></article></main></div>';
    get_footer();
    exit;
}

function tl_refresh_body_class($classes) {
    $classes[] = 'tl-refresh';
    global $post;
    if ($post && isset($post->post_name) && strpos($post->post_name, 'beyond-the-studio-') === 0) {
        $classes[] = 'tl-project-detail';
    }
    if ($post && isset($post->post_name) && $post->post_name === 'elementor-428') {
        $classes[] = 'tl-studio-detail';
    }
    return $classes;
}

function tl_refresh_fonts() {
    echo '<link rel="preconnect" href="https://fonts.googleapis.com">' . "\n";
    echo '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>' . "\n";
    echo '<link rel="stylesheet" id="tl-refresh-fonts" href="https://fonts.googleapis.com/css2?family=Inter:ital,opsz,wght@0,14..32,400..600;1,14..32,400..600&amp;family=Newsreader:ital,opsz,wght@0,6..72,400..600;1,6..72,400..600&amp;display=swap">' . "\n";
}

function tl_refresh_css() {
    ?>
<style id="tl-refresh">
/* ================================================================== *
 * TL design refresh — 2026-09-27
 *
 * One design language over the whole site, layered on top of the Fía
 * polish plugin (which stays as-is). The polish work fixed things page
 * by page; this layer sets the system those fixes should have shared:
 *
 *   - Two typefaces, both actually loaded as web fonts:
 *       Inter       — titles, navigation, captions, labels
 *       Newsreader  — reading text
 *     (Gotham + Felix Titling were named but never loaded, so every
 *     visitor saw whatever happened to be installed; Poppins, Roboto
 *     and Adobe Jenson filled the gaps page by page.)
 *   - A five-step type scale; refresh.js snaps every Elementor heading
 *     onto it by role (data-tl-role) instead of 45 ad-hoc sizes.
 *   - One section header: image band, then title, then intro, all on
 *     the same measure — no type sitting on photographs.
 *   - Flat artwork presentation: no drop-shadow frames, quiet rules.
 *
 * Every selector is prefixed with body.tl-refresh:not(#tl) — the
 * :not(#id) lifts it to ID specificity so it outranks the polish
 * plugin's page-id rules without an arms race of longer selectors.
 * ================================================================== */

body.tl-refresh:not(#tl) {
    --tl-paper: #fff9ef;
    --tl-ink: #1d1c1a;
    --tl-muted: #6c665d;
    --tl-rule: #ddd4c4;
    --tl-accent: #9b2f5f;
    --tl-sans: "Inter", "Helvetica Neue", Arial, sans-serif;
    --tl-serif: "Newsreader", Georgia, "Times New Roman", serif;
    --tl-measure: 40rem;
    --tl-wide: 68rem;
    --tl-gutter: clamp(1.25rem, 5vw, 3rem);

    /* The type scale, in px: Astra sets html to 15px, so rem ran ~6% small. */
    --tl-fs-small: 14px;                                   /* captions, years, eyebrow, footer */
    --tl-fs-label: 16px;                                   /* labels, nav, period ranges */
    --tl-fs-body: clamp(18px, 17px + 0.25vw, 20px);        /* Newsreader reading text */
    --tl-fs-subhead: clamp(19px, 17px + 0.45vw, 22px);
    --tl-fs-title: clamp(24px, 20px + 0.9vw, 30px);
    --tl-fs-display: clamp(34px, 26px + 1.6vw, 46px);

    /* Retarget the polish plugin's own variables at the new faces. */
    --tl-display-face: var(--tl-sans);
    --tl-body-face: var(--tl-serif);

    background: var(--tl-paper) !important;
    color: var(--tl-ink) !important;
    font-family: var(--tl-sans) !important;
    font-feature-settings: "kern", "liga", "calt";
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
}

/* ------------------------------------------------------------------ *
 * 1. Faces — everything is Inter unless it is reading text.
 * ------------------------------------------------------------------ */
body.tl-refresh:not(#tl) :is(h1, h2, h3, h4, h5, h6, .elementor-heading-title,
    .elementor-heading-title a, .elementor-image-box-title, .elementor-image-box-description,
    figcaption, .wp-caption-text, .main-header-menu, .main-header-menu a, .menu-link,
    .ast-builder-menu, .site-footer, .site-footer *, sup, sub, button, input, label,
    .tl-shelf-more, .tl-shelf-title, .tl-home-titles *, .tl-lightbox-caption) {
    font-family: var(--tl-sans) !important;
    text-transform: none !important;
    text-shadow: none !important;
}
body.tl-refresh:not(#tl) :is(.elementor-widget-text-editor, .elementor-widget-text-editor :is(p, li, span, div, blockquote)) {
    font-family: var(--tl-serif) !important;
    font-optical-sizing: auto;
    font-size: var(--tl-fs-body) !important;
    font-weight: 400 !important;
    font-style: normal !important;
    line-height: 1.62 !important;
    letter-spacing: 0 !important;
    color: var(--tl-ink) !important;
}
body.tl-refresh:not(#tl) .elementor-widget-text-editor :is(i, em, cite) { font-style: italic !important; }
body.tl-refresh:not(#tl) .elementor-widget-text-editor :is(b, strong) { font-weight: 600 !important; }
body.tl-refresh:not(#tl) .elementor-widget-text-editor p { margin: 0 0 1em !important; }
body.tl-refresh:not(#tl) .elementor-widget-text-editor p:last-child { margin-bottom: 0 !important; }
body.tl-refresh:not(#tl) .elementor-widget-text-editor sup { font-size: 0.7em !important; }

/* Reading text never runs wider than a comfortable line. */
body.tl-refresh:not(#tl) .elementor-widget-text-editor {
    width: 100% !important;
    max-width: var(--tl-measure) !important;
    flex-shrink: 1 !important;
}
/* Elementor sized these paddings in em, so they grew with the type and
   crushed the column (About's decades went one word per line). The
   measure above governs width; text starts on the same edge as its title. */
body.tl-refresh:not(#tl) .elementor-widget-text-editor > .elementor-widget-container {
    margin-left: 0 !important;
    margin-right: 0 !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
}

/* ------------------------------------------------------------------ *
 * 2. The scale. refresh.js assigns each heading one role.
 * ------------------------------------------------------------------ */
body.tl-refresh:not(#tl) [data-tl-role] {
    font-style: normal !important;
    margin-top: 0 !important;
    color: var(--tl-ink) !important;
}
body.tl-refresh:not(#tl) [data-tl-role="display"] {
    font-size: var(--tl-fs-display) !important;
    font-weight: 500 !important;
    line-height: 1.08 !important;
    letter-spacing: -0.028em !important;
}
body.tl-refresh:not(#tl) [data-tl-role="title"] {
    font-size: var(--tl-fs-title) !important;
    font-weight: 500 !important;
    line-height: 1.18 !important;
    letter-spacing: -0.018em !important;
}
body.tl-refresh:not(#tl) [data-tl-role="subhead"] {
    font-size: var(--tl-fs-subhead) !important;
    font-weight: 500 !important;
    line-height: 1.3 !important;
    letter-spacing: -0.01em !important;
}
body.tl-refresh:not(#tl) [data-tl-role="label"] {
    font-size: var(--tl-fs-label) !important;
    font-weight: 500 !important;
    line-height: 1.35 !important;
    letter-spacing: -0.004em !important;
}
body.tl-refresh:not(#tl) [data-tl-role="caption"] {
    font-size: var(--tl-fs-small) !important;
    font-weight: 500 !important;
    line-height: 1.4 !important;
    letter-spacing: 0 !important;
}
body.tl-refresh:not(#tl) [data-tl-role="meta"] {
    font-size: var(--tl-fs-small) !important;
    font-weight: 400 !important;
    line-height: 1.4 !important;
    letter-spacing: 0 !important;
    color: var(--tl-muted) !important;
    font-variant-numeric: tabular-nums;
}
body.tl-refresh:not(#tl) [data-tl-role] :is(i, em) { font-style: italic !important; }
body.tl-refresh:not(#tl) [data-tl-role="caption"] + *,
body.tl-refresh:not(#tl) .elementor-widget-heading:has([data-tl-role="caption"]) + .elementor-widget-heading:has([data-tl-role="meta"]) {
    margin-top: 0.1rem !important;
}
/* Captions from outside the heading widgets share the same floor. */
body.tl-refresh:not(#tl) :is(figcaption, .wp-caption-text, .elementor-image-box-description, .tl-lightbox-caption) {
    font-size: var(--tl-fs-small) !important;
    line-height: 1.45 !important;
}
body.tl-refresh:not(#tl) :is(.tl-context-venue-year, .tl-shelf-more) {
    font-size: var(--tl-fs-small) !important;
}
body.tl-refresh:not(#tl) .tl-context-venue-year { color: var(--tl-muted) !important; }
body.tl-refresh:not(#tl) .elementor-heading-title span { font-size: inherit !important; }
/* A caption belongs to the image above it. */
