.thomaslawson.com/wp-content/uploads/2023/12/403-Video-Data-Bank-Profile.pdf","fix":false},"497-robbins-interview-with-tl-1-scaled.jpg":{"s":"elementor-1796","t":"Robbins Interview","m":"D.a. Robbins, Arts Magazine, September 1984","h":"https://www.thomaslawson.com/wp-content/uploads/2023/12/497-Robbins-Interview-with-TL.pdf","fix":false},"620-robert-rooney-pool-side-1.jpg":{"s":"elementor-1796","t":"Robert Rooney Pool Side","m":"Robert Rooney, Art & Text, Pool-Side issue, Victoria College, Australia, December-January 1982","h":"https://www.thomaslawson.com/wp-content/uploads/2023/12/620-Robert-Rooney-Pool-Side.pdf","fix":false},"793-cae-art-papers-1-scaled.jpg":{"s":"elementor-1796","t":"CAE Art Papers","m":"Critical Art Ensemble, Art Papers, Contemporary Art in the Southeast, January/February 1989","h":"https://www.thomaslawson.com/wp-content/uploads/2023/12/793-CAE-Art-Papers.pdf","fix":false},"cover-for-christopher-howard-interview.png":{"s":"elementor-1796","t":"Christopher Howard","m":"Christopher Howard, Artforum, May 7 2011","h":"https://www.thomaslawson.com/wp-content/uploads/2023/12/Christopher-Howard-interview-about-EOB-2011.pdf","fix":false},"cover-for-mcevilly-sischy-interview.png":{"s":"elementor-1796","t":"McEvilly Sischy","m":"Thomas McEvilly and Ingrid Sischy, Artforum, February 1988","h":"https://www.thomaslawson.com/wp-content/uploads/2023/12/McEvilly-and-Sischy-interview-TLawson-1988.pdf","fix":false},"spike-71-couples-cover-web_f4b47d70-c6c8-4448-ba6c-5ab99feb149d.jpeg":{"s":"elementor-395","t":"Civilization and the Landscape of Discontent at Nature Morte, New York, 1984","m":"Spike Art Magazine, Issue 71, Summer, 2022","h":"https://www.thomaslawson.com/wp-content/uploads/2024/01/71_Spike_Exhibition_History_10.pdf","fix":false},"359-empire-1.jpg":{"s":"elementor-395","t":"Empire, with Russell Ferguson","m":"Glasgow; Brunswick St., reprinted by Eindhoven: Stedelijk van Abbsemuseum, 1998","h":"https://www.thomaslawson.com/wp-content/uploads/2023/0